    "aliasSources": [],
    "classificationEvidence": [],
    "pathwayPeriodNotes": [
      "卢米安考虑如何唤醒安小天时，提到恶棍途径序列7“那术师”能举行新生仪式，因而把格林等恩赐者列入考虑。后文明确称梦境都市中的格林是“伟大母亲”的恩赐者。卢米安讨论的是举行仪式的条件，格林个人的序列和受赐时间仍未明。见《宿命之环》第六部，第八十九章《出乎意料的拜访者》、第一百零一章《我不信》。"
    ],
